## zstd and BLAKE3 tests: reference frames (made by the zstd library at levels 19 and 3, with
## Huffman literals, FSE tables and a checksum), encoder round trips, corruption handling.
import std/[unittest, strutils, os]
import photocraft/[zstd, blake3]

proc unhex(s: string): seq[byte] =
  for i in countup(0, s.len - 2, 2): result.add byte(parseHexInt(s[i .. i + 1]))

proc bytesOf(s: string): seq[byte] =
  for c in s: result.add byte(c)

const
  Level19 = ""
  Level3x20 = ""

let text = bytesOf(readFile(currentSourcePath.parentDir / ".." / ".." / "crates" / "compose" / "src" / "lib.rs"))[0 ..< 3000]

suite "zstd":
  test "xxh64 vectors":
    check xxh64([]) == 0xEF46DB3751D8E999'u64
    check xxh64(bytesOf("a")) == 0xD24EC4F1A98C6E5B'u64

  test "decodes reference frames":
    check zstdDecompress(unhex(Level19)) == text
    var t20: seq[byte]
    for _ in 0 ..< 20: t20.add text
    check zstdDecompress(unhex(Level3x20)) == t20

  test "encoder round trips and compresses":
    var tile = newSeq[byte](262144)
    for i in 0 ..< tile.len: tile[i] = byte((i div 7) mod 256)
    for data in [newSeq[byte](), bytesOf("x"), text, tile, newSeq[byte](300_000)]:
      let z = zstdCompress(data)
      check zstdDecompress(z) == data
    check zstdCompress(tile).len < 2000
    var rnd = newSeq[byte](200_000)
    var s = 12345'u32
    for b in rnd.mitems:
      s = s * 1664525 + 1013904223
      b = byte(s shr 24)
    check zstdDecompress(zstdCompress(rnd)) == rnd

  test "corrupt input raises":
    var z = unhex(Level19)
    z[z.len div 2] = z[z.len div 2] xor 0x55
    expect ZstdError: discard zstdDecompress(z)
    expect ZstdError: discard zstdDecompress(unhex(Level19)[0 ..< 100])
    expect ZstdError: discard zstdDecompress(bytesOf("not zstd"))
    expect ZstdError: discard zstdDecompress(zstdCompress(text), maxOut = 100)

suite "blake3":
  test "reference vectors":
    check blake3Hex([]) == "af1349b9f5f9a1a6a0404dea36dcc9499bcb25c9adc112b7cc9a93cae41f3262"
    for (n, want) in [(1023, "10108970eeda3eb932baac1428c7a2163b0e924c9a9e25b35bba72b28f70bd11"),
                      (1025, "d00278ae47eb27b34faecf67b4fe263f82d5412916c1ffd97c8cb7fb814b8444"),
                      (102400, "bc3e3d41a1146b069abffad3c0d44860cf664390afce4d9661f7902e7943e085")]:
      var d = newSeq[byte](n)
      for i in 0 ..< n: d[i] = byte(i mod 251)
      check blake3Hex(d) == want

suite "zstd streaming reads (ruzstd)":
  test "frames are read block by block up to the cap":
    var d: seq[byte]
    for i in 0 ..< 300_000: d.add byte((i * 13) mod 251)
    let z = zstdCompress(d)
    var pos = 0
    check zstdReadFrame(z, pos, d.len + 1, 64 shl 20) == d
    check pos == z.len
    pos = 0
    check zstdReadFrame(z, pos, 1000, 64 shl 20) == d[0 ..< 1000]
    # Windows above the ceiling and skippable frames are errors, not skipped.
    pos = 0
    expect ZstdError: discard zstdReadFrame(z, pos, 10, 1000)
    var skip = @[0x50'u8, 0x2A, 0x4D, 0x18, 0, 0, 0, 0]
    pos = 0
    expect ZstdError: discard zstdReadFrame(skip, pos, 10, 64 shl 20)
